#include "gpsd_config.h"  /* must be before all includes */

#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>

#include "gpsd.h"

#define kMinInputLength 10
#define kMaxInputLength 9216

extern int LLVMFuzzerTestOneInput(const uint8_t *Data, size_t Size)
{//gpsd/tests//test_packet.c

    if (Size < kMinInputLength || Size > kMaxInputLength){
        return 0;
    }

    {
        struct gps_lexer_t lexer;

        lexer_init(&lexer);
        lexer.errout.debug = 0;

        memcpy(lexer.inbufptr = lexer.inbuffer, Data, Size);
        lexer.inbuflen = Size;

        packet_parse(&lexer);
    }
    {
        struct gps_lexer_t lexer;
        int nullfd = open("/dev/null", O_RDONLY);
        ssize_t st;

        lexer_init(&lexer);
        lexer.errout.debug = 0;

        memcpy(lexer.inbufptr = lexer.inbuffer, Data, Size);
        lexer.inbuflen = Size;

        do {
            st = packet_get(nullfd, &lexer);
        } while (st > 0);

        close(nullfd);
    }

    return 0;
}
TARGET=Fuzzer

#File
jsonEXE=FuzzJson
packetEXE=FuzzPacket

#Compiler Flags
DIR=$(shell ls -d ../gpsd*~dev/)
INC=-I$(DIR)include/
EXTCFLAGS=-Wall -Werror -pthread -std=c99
LibINC=-L$(DIR)
LibFLAGS=$(LIB_FUZZING_ENGINE) -lgpsd -lgps_static

all: $(TARGET)

#SETUP
$(TARGET):
        $(CC) $(CFLAGS) $(INC) $(EXTCFLAGS) -c $(jsonEXE).c
        $(CC) $(CFLAGS) $(INC) $(EXTCFLAGS) -c $(packetEXE).c

        $(CXX) $(CFLAGS) $(LibINC) -o $(jsonEXE) $(jsonEXE).o  $(LibFLAGS)
        $(CXX) $(CFLAGS) $(LibINC) -o $(packetEXE) $(packetEXE).o  $(LibFLAGS)

clean:
        rm $(jsonEXE) $(packetEXE) *.o

.PHONY: all clean
